Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<div style="font-weight:700;margin-bottom:2px">Polar HF molecules in a field</div>

<div style="font-weight:600">Panel</div>
<div style="display:flex;gap:4px;flex-wrap:wrap">
  <button id="btnPanelA" class="active">(a) No field</button>
  <button id="btnPanelB">(b) Field applied</button>
</div>

<label style="margin-top:6px">Field strength E = <span id="valE">0.00</span>
  <input type="range" id="fieldStrength" min="0" max="1" step="0.01" value="0">
</label>

<button id="btnSwitch" style="margin-top:4px">Switch field on / off</button>

<div style="border-top:1px solid #dcdfe3;margin:8px 0 4px"></div>
<div style="font-weight:600">Guided demo</div>
<div style="display:flex;gap:4px">
  <button id="btnPrev">◀ Prev</button>
  <button id="btnNext">Next ▶</button>
</div>
<div id="stepTitle" style="font-weight:600;margin-top:4px">1. No field: random orientation</div>
<div id="stepText" style="line-height:1.4;color:#333">Between two uncharged gray plates, five HF molecules tumble at random angles — the δ+ hydrogen ends point in all directions, so the sample has no net dipole.</div>

<div style="border-top:1px solid #dcdfe3;margin:8px 0 4px"></div>
<div style="color:#555;line-height:1.4">Drag in the figure to orbit (limited to ±50° / ±30°) and confirm the dipoles line up along one axis in space. Hover or click a molecule or plate for an explanation.</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── Element spec ──────────────────────────────────────────────────────────
   left plate        → BoxGeometry(0.18,7.2,1.6) @x=-3.09, CanvasTexture gradient
                       (gray #EFEFEF→#8C8C8C / tan #C9B78A→#7E7351) + EdgesGeometry black
   right plate       → same box @x=+3.09, mirrored
   field region      → BoxGeometry(6.0,7.2,1.6) MeshBasicMaterial #F5E7C1, opacity .85, depthWrite false
   HF molecule x5    → Group[ SphereGeometry(0.55) green #56A93C Phong,
                              SphereGeometry(0.34) white #FFFFFF Phong ], centers 0.62 apart
   δ− / δ+ labels    → addLabel anchored to Object3D children of each molecule group
   − / + glyphs      → addLabel at (±2.75, 3.35, 0)
   'Electric field'  → addLabel at (-0.2,4.3,0) + Line (0.15,4.05,0)→(0.75,3.05,0) black
   caption (a)/(b)   → addLabel at (0,-4.4,0)
   lighting          → HemisphereLight + DirectionalLight upper-left for sphere highlights
──────────────────────────────────────────────────────────────────────────── */

const D2R = THREE.MathUtils.degToRad;

/* ── Lighting ─────────────────────────────────────────────────────────── */
scene.add(new THREE.HemisphereLight(0xffffff, 0xbbbbbb, 0.85));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.75);
keyLight.position.set(-5, 7, 9);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.25);
fillLight.position.set(4, -3, 6);
scene.add(fillLight);

/* ── Plate textures & materials ───────────────────────────────────────── */
function gradientTexture(top, bottom) {
  const cv = document.createElement('canvas');
  cv.width = 8; cv.height = 256;
  const ctx = cv.getContext('2d');
  const g = ctx.createLinearGradient(0, 0, 0, 256);
  g.addColorStop(0, top);
  g.addColorStop(1, bottom);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 8, 256);
  const tex = new THREE.CanvasTexture(cv);
  if ('colorSpace' in tex) tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

const grayMat = new THREE.MeshPhongMaterial({
  map: gradientTexture('#EFEFEF', '#8C8C8C'), shininess: 18, specular: 0x333333
});
const tanMat = new THREE.MeshPhongMaterial({
  map: gradientTexture('#C9B78A', '#7E7351'), shininess: 12, specular: 0x222222
});

const plateGeo = new THREE.BoxGeometry(0.18, 7.2, 1.6);
const plateEdgeGeo = new THREE.EdgesGeometry(plateGeo);
const edgeMat = new THREE.LineBasicMaterial({ color: 0x1a1a1a });

function makePlate(cx, title, body) {
  const mesh = new THREE.Mesh(plateGeo, grayMat);
  mesh.position.set(cx, 0, 0);
  mesh.add(new THREE.LineSegments(plateEdgeGeo, edgeMat));
  scene.add(mesh);
  registerInteractive(mesh, { title, body, tooltip: title });
  return mesh;
}

const plateL = makePlate(-3.09, 'Left capacitor plate',
  'Uncharged in panel (a). In panel (b) it carries a negative charge (−), so the δ+ hydrogen end of every HF dipole is attracted toward it.');
const plateR = makePlate(3.09, 'Right capacitor plate',
  'Uncharged in panel (a). In panel (b) it carries a positive charge (+), attracting the δ− fluorine end of every HF dipole.');

/* ── Pale-yellow field region (panel b) ───────────────────────────────── */
const fieldBoxMat = new THREE.MeshBasicMaterial({
  color: 0xF5E7C1, transparent: true, opacity: 0.0,
  depthWrite: false, side: THREE.DoubleSide
});
const fieldBox = new THREE.Mesh(new THREE.BoxGeometry(6.0, 7.2, 1.6), fieldBoxMat);
fieldBox.renderOrder = -1;
scene.add(fieldBox);
registerInteractive(fieldBox, {
  title: 'Electric field region',
  body: 'The uniform field points from the + plate (right) toward the − plate (left). It exerts a torque on each permanent dipole until the molecular axis lies along the field.'
});

/* ── 'Electric field' leader line ─────────────────────────────────────── */
const leaderMat = new THREE.LineBasicMaterial({ color: 0x000000 });
const leaderLine = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(0.15, 4.05, 0.0),
    new THREE.Vector3(0.75, 3.05, 0.0)
  ]), leaderMat);
leaderLine.visible = false;
scene.add(leaderLine);

/* ── HF molecules ─────────────────────────────────────────────────────── */
const fMat = new THREE.MeshPhongMaterial({ color: 0x56A93C, specular: 0xdfffd0, shininess: 40 });
const hMat = new THREE.MeshPhongMaterial({ color: 0xffffff, specular: 0xffffff, shininess: 40 });
const fGeo = new THREE.SphereGeometry(0.55, 40, 28);
const hGeo = new THREE.SphereGeometry(0.34, 32, 22);

const molData = [
  { ax: 1.25, ay: 2.30, ang: 35, bx: 1.30, by: 2.60, j: 0.60, z: 0.25 },
  { ax: -1.60, ay: 0.95, ang: 138, bx: -0.60, by: 1.20, j: -0.85, z: -0.20 },
  { ax: 0.25, ay: -0.15, ang: -62, bx: -0.55, by: -0.10, j: 0.35, z: 0.15 },
  { ax: -1.65, ay: -1.95, ang: -58, bx: 0.95, by: -1.55, j: -0.50, z: 0.30 },
  { ax: 1.00, ay: -2.25, ang: 18, bx: -1.30, by: -2.60, j: 0.90, z: -0.25 }
];

const mols = [];
molData.forEach((m, i) => {
  const g = new THREE.Group();
  const f = new THREE.Mesh(fGeo, fMat);
  const h = new THREE.Mesh(hGeo, hMat);
  h.position.set(0.62, 0, 0);
  g.add(f, h);

  const aMinus = new THREE.Object3D(); aMinus.position.set(-1.10, 0, 0); g.add(aMinus);
  const aPlus = new THREE.Object3D(); aPlus.position.set(1.51, 0, 0); g.add(aPlus);

  g.position.set(m.ax, m.ay, m.z);
  g.rotation.z = D2R(m.ang);
  scene.add(g);
  registerInteractive(g, {
    title: 'HF molecule (a permanent dipole)',
    body: 'Fluorine (large green sphere) pulls bonding electrons away from hydrogen (small white sphere), giving δ− on F and δ+ on H. The molecule is a permanent dipole, so an external field twists it into alignment.',
    tooltip: 'HF dipole'
  });
  mols.push({ g, data: m, aMinus, aPlus, s: 0 });
});

/* ── Camera (after geometry) ──────────────────────────────────────────── */
setCameraView({
  projection: 'perspective',
  azimuthDeg: 90,
  elevationDeg: 8,
  rollDeg: 0,
  heightFraction: 0.7
});
controls.minAzimuthAngle = D2R(-50);
controls.maxAzimuthAngle = D2R(50);
controls.minPolarAngle = D2R(60);
controls.maxPolarAngle = D2R(120);
document.getElementById('btnReset').style.display = '';

/* ── Labels ───────────────────────────────────────────────────────────── */
const DELTA_STYLE = 'font-family:Georgia,\'Times New Roman\',serif;font-style:italic;';
function deltaHTML(sign) { return `<span style="${DELTA_STYLE}">&delta;${sign}</span>`; }

const tmpV = new THREE.Vector3();
mols.forEach(m => {
  m.lblMinus = addLabel(deltaHTML('&minus;'), new THREE.Vector3(), { fontSize: '15px' });
  m.lblPlus = addLabel(deltaHTML('+'), new THREE.Vector3(), { fontSize: '15px' });
});

const lblMinusPlate = addLabel('<b>&minus;</b>', new THREE.Vector3(-2.75, 3.35, 0), { fontSize: '20px' });
const lblPlusPlate = addLabel('<b>+</b>', new THREE.Vector3(2.75, 3.35, 0), { fontSize: '20px' });
const lblField = addLabel('Electric field', new THREE.Vector3(-0.2, 4.35, 0), { fontSize: '14px' });
const lblCaption = addLabel('(a)', new THREE.Vector3(0, -4.4, 0), { fontSize: '15px' });

function setLabelOpacity(entry, v) { entry.div.style.opacity = String(v); }
setLabelOpacity(lblMinusPlate, 0);
setLabelOpacity(lblPlusPlate, 0);
setLabelOpacity(lblField, 0);

/* ── State: alignment s (0 = panel a, 1 = panel b) ────────────────────── */
let sTarget = 0;
let animated = false;
let animStart = 0;
let panelB = false;
let panelAmt = 0;

const sliderE = document.getElementById('fieldStrength');
const valE = document.getElementById('valE');
const btnA = document.getElementById('btnPanelA');
const btnB = document.getElementById('btnPanelB');

function setPanel(isB) {
  panelB = isB;
