// @FIGURE_CODE_BEGIN
/* ── Element spec ──────────────────────────────────────────────────────────
   left plate         → BoxGeometry(0.18,7.2,1.6) @x=-3.09, MeshBasicMaterial +
                        CanvasTexture (gray #FFFFFF→#6A6A6A / tan #E3D3A6→#6A6047
                        plus bright highlight band) + EdgesGeometry #000 outline
   right plate        → same box @x=+3.09 (mirrored texture)
   field region (b)   → back PlaneGeometry(6.0,7.2) @z=-0.8  #F5E7C1 op .96
                        + top PlaneGeometry(6.0,1.6) @y=+3.6 (slightly darker)
                        + bottom PlaneGeometry(6.0,1.6) @y=-3.6
   HF molecule ×5     → Group[ SphereGeometry(0.55) green #63B94A Phong,
                               SphereGeometry(0.34) white #FFFFFF Phong ], 0.62 apart
   δ− / δ+ labels     → addLabel (serif italic, near-black, large) on Object3D anchors
   − / + plate glyphs → addLabel at (∓2.72, 3.38, 0.8) bold, largest glyphs
   'Electric field'   → addLabel at (-0.2,4.35,0) + Line (0.15,4.05)→(0.75,3.05) black
   caption (a)/(b)    → addLabel at (0,-4.45,0)
   lighting           → HemisphereLight + key DirectionalLight upper-left (highlights)
──────────────────────────────────────────────────────────────────────────── */

const D2R = THREE.MathUtils.degToRad;

/* ── Lighting (tuned so materials render at ~source brightness) ───────── */
scene.add(new THREE.HemisphereLight(0xffffff, 0xdddddd, 0.55));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.50);
keyLight.position.set(-4, 6, 8);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.12);
fillLight.position.set(5, -3, 4);
scene.add(fillLight);

/* ── Plate textures (unlit, so the printed gradient survives exactly) ─── */
function plateTexture(stops, bandCenter) {
  const cv = document.createElement('canvas');
  cv.width = 128; cv.height = 512;
  const ctx = cv.getContext('2d');
  const g = ctx.createLinearGradient(0, 0, 0, 512);
  stops.forEach(s => g.addColorStop(s[0], s[1]));
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 128, 512);
  // metallic highlight band running along the plate's receding direction
  const hb = ctx.createLinearGradient(0, 0, 128, 0);
  hb.addColorStop(0, 'rgba(255,255,255,0)');
  hb.addColorStop(Math.max(0.02, bandCenter - 0.16), 'rgba(255,255,255,0)');
  hb.addColorStop(bandCenter, 'rgba(255,255,255,0.72)');
  hb.addColorStop(Math.min(0.98, bandCenter + 0.18), 'rgba(255,255,255,0)');
  hb.addColorStop(1, 'rgba(0,0,0,0.10)');
  ctx.fillStyle = hb;
  ctx.fillRect(0, 0, 128, 512);
  const tex = new THREE.CanvasTexture(cv);
  if ('colorSpace' in tex) tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  return tex;
}

const grayMat = new THREE.MeshBasicMaterial({
  map: plateTexture([[0, '#FFFFFF'], [0.30, '#E6E6E6'], [0.62, '#A6A6A6'], [1, '#6A6A6A']], 0.34)
});
const tanMat = new THREE.MeshBasicMaterial({
  map: plateTexture([[0, '#E6D7AC'], [0.30, '#D2C08F'], [0.62, '#9A8C63'], [1, '#6A6047']], 0.34)
});

const plateGeo = new THREE.BoxGeometry(0.18, 7.2, 1.6);
const plateEdgeGeo = new THREE.EdgesGeometry(plateGeo);
const edgeMat = new THREE.LineBasicMaterial({ color: 0x000000 });

function makePlate(cx, title, body) {
  const mesh = new THREE.Mesh(plateGeo, grayMat);
  mesh.position.set(cx, 0, 0);
  mesh.add(new THREE.LineSegments(plateEdgeGeo, edgeMat));
  scene.add(mesh);
  registerInteractive(mesh, { title, body, tooltip: title });
  return mesh;
}

const plateL = makePlate(-3.09, 'Left capacitor plate',
  'Uncharged in panel (a). In panel (b) it carries a negative charge (−), so the δ+ hydrogen end of every HF dipole is attracted toward it.');
const plateR = makePlate(3.09, 'Right capacitor plate',
  'Uncharged in panel (a). In panel (b) it carries a positive charge (+), attracting the δ− fluorine end of every HF dipole.');

/* ── Pale-yellow field region (panel b): back + top + bottom faces only, so
      the near-opaque tint never hides the molecules in front of it ─────── */
const fieldMats = [];
function fieldFace(w, h, pos, rot, color, op) {
  const mat = new THREE.MeshBasicMaterial({
    color, transparent: true, opacity: 0, depthWrite: false, side: THREE.DoubleSide
  });
  mat.userData = { full: op };
  fieldMats.push(mat);
  const m = new THREE.Mesh(new THREE.PlaneGeometry(w, h), mat);
  m.position.copy(pos);
  m.rotation.copy(rot);
  m.renderOrder = -1;
  scene.add(m);
  return m;
}
const fieldBack = fieldFace(6.0, 7.2, new THREE.Vector3(0, 0, -0.8),
  new THREE.Euler(0, 0, 0), 0xF5E7C1, 0.97);
fieldFace(6.0, 1.6, new THREE.Vector3(0, 3.6, 0),
  new THREE.Euler(-Math.PI / 2, 0, 0), 0xEFDFB4, 0.95);
fieldFace(6.0, 1.6, new THREE.Vector3(0, -3.6, 0),
  new THREE.Euler(-Math.PI / 2, 0, 0), 0xE8D7A9, 0.95);

registerInteractive(fieldBack, {
  title: 'Electric field region',
  body: 'The uniform field points from the + plate (right) toward the − plate (left). It exerts a torque on each permanent dipole until the molecular axis lies along the field.',
  tooltip: 'Electric field region'
});

/* ── 'Electric field' leader line ─────────────────────────────────────── */
const leaderMat = new THREE.LineBasicMaterial({ color: 0x000000, transparent: true, opacity: 1 });
const leaderLine = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(0.15, 4.05, 0.0),
    new THREE.Vector3(0.75, 3.05, 0.0)
  ]), leaderMat);
leaderLine.visible = false;
scene.add(leaderLine);

/* ── HF molecules ─────────────────────────────────────────────────────── */
const fMat = new THREE.MeshPhongMaterial({
  color: 0x63B94A, emissive: 0x15300f, specular: 0xd8f5c4, shininess: 45
});
const hMat = new THREE.MeshPhongMaterial({
  color: 0xffffff, emissive: 0x262626, specular: 0xffffff, shininess: 60
});
const fGeo = new THREE.SphereGeometry(0.55, 48, 32);
const hGeo = new THREE.SphereGeometry(0.34, 36, 24);

const molData = [
  { ax: 1.25, ay: 2.30, ang: 35, bx: 1.30, by: 2.60, j: 0.60, z: 0.25 },
  { ax: -1.60, ay: 0.95, ang: 138, bx: -0.60, by: 1.20, j: -0.85, z: -0.20 },
  { ax: 0.25, ay: -0.15, ang: -62, bx: -0.55, by: -0.10, j: 0.35, z: 0.15 },
  { ax: -1.65, ay: -1.95, ang: -58, bx: 0.95, by: -1.55, j: -0.50, z: 0.30 },
  { ax: 1.00, ay: -2.25, ang: 18, bx: -1.30, by: -2.60, j: 0.90, z: -0.25 }
];

const mols = [];
molData.forEach((m) => {
  const g = new THREE.Group();
  const f = new THREE.Mesh(fGeo, fMat);
  const h = new THREE.Mesh(hGeo, hMat);
  h.position.set(0.62, 0, 0);
  g.add(f, h);

  const aMinus = new THREE.Object3D(); aMinus.position.set(-1.10, 0, 0); g.add(aMinus);
  const aPlus = new THREE.Object3D(); aPlus.position.set(1.51, 0, 0); g.add(aPlus);

  g.position.set(m.ax, m.ay, m.z);
  g.rotation.z = D2R(m.ang);
  g.userData.initialAngle = m.ang;
  scene.add(g);
  registerInteractive(g, {
    title: 'HF molecule (a permanent dipole)',
    body: 'Fluorine (large green sphere) pulls bonding electrons away from hydrogen (small white sphere), giving δ− on F and δ+ on H. The molecule is a permanent dipole, so an external field twists it into alignment.',
    tooltip: 'HF dipole'
