/* ── Camera (after geometry) ──────────────────────────────────────────── */
setCameraView({
  projection: 'perspective',
  azimuthDeg: 90,
  elevationDeg: 8,
  rollDeg: 0,
  heightFraction: 0.7
});
controls.minAzimuthAngle = D2R(-50) + Math.PI / 2;
controls.maxAzimuthAngle = D2R(50) + Math.PI / 2;
controls.minPolarAngle = D2R(60);
controls.maxPolarAngle = D2R(120);
document.getElementById('btnReset').style.display = '';

/* ── Labels ────────────────────────────────────────────────────────────
   The scaffold shrinks perspective labels by 8/distance, so pre-multiply the
   requested on-screen size by distance/8 to get the intended pixel height. */
const labelK = Math.max(1, camera.position.distanceTo(controls.target) / 8);
const fpx = (n) => (n * labelK).toFixed(1) + 'px';

const SERIF = "Georgia,'Times New Roman',serif";
const deltaHTML = (sign) =>
  `<span style="font-family:${SERIF};font-style:italic;letter-spacing:0.5px">&delta;${sign}</span>`;

const tmpV = new THREE.Vector3();
mols.forEach(m => {
  m.lblMinus = addLabel(deltaHTML('&minus;'), new THREE.Vector3(),
    { fontSize: fpx(20), color: '#0d0d0d' });
  m.lblPlus = addLabel(deltaHTML('+'), new THREE.Vector3(),
    { fontSize: fpx(20), color: '#0d0d0d' });
});

const lblMinusPlate = addLabel(
  `<span style="font-family:${SERIF}">&minus;</span>`,
  new THREE.Vector3(-2.72, 3.38, 0.80), { fontSize: fpx(28), color: '#000', bold: true });
const lblPlusPlate = addLabel(
  `<span style="font-family:${SERIF}">+</span>`,
  new THREE.Vector3(2.72, 3.38, 0.80), { fontSize: fpx(28), color: '#000', bold: true });
const lblField = addLabel(
  `<span style="font-family:sans-serif">Electric field</span>`,
  new THREE.Vector3(-0.2, 4.35, 0), { fontSize: fpx(16), color: '#000' });
const lblCaption = addLabel(
  `<span style="font-family:sans-serif">(a)</span>`,
  new THREE.Vector3(0, -4.45, 0), { fontSize: fpx(18), color: '#000' });

function setLabelOpacity(entry, v) { entry.div.style.opacity = String(v); }
setLabelOpacity(lblMinusPlate, 0);
setLabelOpacity(lblPlusPlate, 0);
setLabelOpacity(lblField, 0);

/* ── State: alignment s (0 = panel a, 1 = panel b) ────────────────────── */
let sTarget = 0;
let animated = false;
let animStart = 0;
let panelB = false;
let panelAmt = 0;

const sliderE = document.getElementById('fieldStrength');
const valE = document.getElementById('valE');
const btnA = document.getElementById('btnPanelA');
const btnB = document.getElementById('btnPanelB');

function setPanel(isB) {
  panelB = isB;
  btnA.classList.toggle('active', !isB);
  btnB.classList.toggle('active', isB);
  plateL.material = isB ? tanMat : grayMat;
  plateR.material = isB ? tanMat : grayMat;
  lblCaption.div.innerHTML = `<span style="font-family:sans-serif">${isB ? '(b)' : '(a)'}</span>`;
}

function setStrength(v, withAnim) {
  sTarget = Math.max(0, Math.min(1, v));
  sliderE.value = String(sTarget);
  valE.textContent = sTarget.toFixed(2);
  if (withAnim) {
    animated = true;
    animStart = performance.now();
  } else {
    animated = false;
    mols.forEach(m => { m.s = sTarget; });
  }
}

sliderE.addEventListener('input', () => {
  const v = parseFloat(sliderE.value);
  setStrength(v, false);
  if (v > 0 && !panelB) setPanel(true);
  if (v === 0 && panelB) setPanel(false);
});
btnA.addEventListener('click', () => { setPanel(false); setStrength(0, true); });
btnB.addEventListener('click', () => { setPanel(true); setStrength(1, true); });
document.getElementById('btnSwitch').addEventListener('click', () => {
  const on = sTarget < 0.5;
  setPanel(on);
  setStrength(on ? 1 : 0, true);
});

/* ── Guided demo steps ────────────────────────────────────────────────── */
const steps = [
  {
    title: 'No field: random orientation',
    text: 'Between two uncharged gray plates, five HF molecules tumble at random angles — the δ+ hydrogen ends point in all directions, so the sample has no net dipole.',
    panel: false, strength: 0
  },
  {
    title: 'Weak field: partial alignment',
    text: 'Charging the plates fills the gap with a pale-yellow field region. At low field strength the molecules tilt toward alignment but thermal motion keeps them scattered.',
    panel: true, strength: 0.35
  },
  {
    title: 'Strong field: full alignment',
    text: 'At high field strength every dipole locks in: all δ+ hydrogens face the negative left plate and all δ− fluorines face the positive right plate.',
    panel: true, strength: 1
  },
  {
    title: 'Field off again',
    text: 'Removing the field lets the molecules relax back to disordered orientations, showing the ordering is imposed by the field, not intrinsic to the liquid.',
    panel: false, strength: 0
  }
];
let stepIndex = 0;
function goToStep(i) {
  stepIndex = (i + steps.length) % steps.length;
  const s = steps[stepIndex];
  setPanel(s.panel);
  setStrength(s.strength, true);
  document.getElementById('stepTitle').textContent = `${stepIndex + 1}. ${s.title}`;
  document.getElementById('stepText').textContent = s.text;
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIndex + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIndex - 1));

/* ── Per-frame update: dipole rotation, positions, label anchors ──────── */
let lastT = performance.now();
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - lastT) / 1000);
  lastT = now;

  // damped easing toward sTarget, staggered ~80 ms per molecule
  if (animated) {
    let settled = true;
    mols.forEach((m, i) => {
      if (now >= animStart + i * 80) {
        m.s += (sTarget - m.s) * (1 - Math.exp(-dt / 0.19));
      }
      if (Math.abs(m.s - sTarget) > 0.002) settled = false;
    });
    if (settled) { mols.forEach(m => { m.s = sTarget; }); animated = false; }
  }

  // panel visuals fade
  const panelGoal = panelB ? 1 : 0;
  panelAmt += (panelGoal - panelAmt) * (1 - Math.exp(-dt / 0.15));
  fieldMats.forEach(mat => { mat.opacity = mat.userData.full * panelAmt; });
  setLabelOpacity(lblMinusPlate, panelAmt);
  setLabelOpacity(lblPlusPlate, panelAmt);
  setLabelOpacity(lblField, panelAmt);
  leaderLine.visible = panelAmt > 0.05;
  leaderMat.opacity = panelAmt;

  mols.forEach(m => {
    const s = m.s, d = m.data;
    const noise = d.j * 4 * s * (1 - s) * 25;      // 0 at s=0 and s=1
    const ang = (1 - s) * d.ang + s * 180 + noise;
    m.g.rotation.z = D2R(ang);
    m.g.position.set(
      (1 - s) * d.ax + s * d.bx,
      (1 - s) * d.ay + s * d.by,
      d.z * (1 - s)
    );
    m.g.updateMatrixWorld(true);
    m.lblMinus.pos.copy(m.aMinus.getWorldPosition(tmpV));
    m.lblPlus.pos.copy(m.aPlus.getWorldPosition(tmpV));
  });
}
tick();
